(()=>{const root=document.querySelector('.package-comparison');if(!root)return;const controls=root.querySelector('.comparison-switch'),buttons=[...controls.querySelectorAll('button')],cells=[...root.querySelectorAll('[data-plan]')];function select(value){buttons.forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.package===value)));cells.forEach(c=>c.toggleAttribute('data-current',c.dataset.plan===value));}const narrow=matchMedia('(max-width:800px)');function resize(){root.querySelectorAll('.comparison-group th').forEach(c=>c.colSpan=narrow.matches?2:4)}resize();narrow.addEventListener('change',resize);select('1');root.classList.add('comparison-ready');root.querySelector('table').classList.add('mobile-enhanced');controls.hidden=false;const header=document.querySelector('header');function offsets(){root.style.setProperty('--site-header-height',header.getBoundingClientRect().height+'px');root.style.setProperty('--comparison-switch-height',(narrow.matches?controls.getBoundingClientRect().height:0)+'px')}const observer=new ResizeObserver(offsets);observer.observe(header);observer.observe(controls);narrow.addEventListener('change',offsets);offsets();buttons.forEach(b=>b.addEventListener('click',()=>select(b.dataset.package)));})();
